"""Step 181: Maya option windows of the Surfaces menu (same spec as operators/option_windows.py; option_windows._extend
appends ``WINDOWS``). Titles, field labels and factory values: Maya 2022's option
windows).
Fields Blender / the kit can't follow are listed as ``missing``. Operators:
operators/surfaces_maya.py (docs/steps/step_181.md operator table). Values are Maya values (lengths in Maya units)."""
from ..i18n import source_message as _dcc_source, display_message as _dcc_display, format_message as _dcc_format
from ..i18n import tr as _zh, enum_items as _zh_enum, native as _zh_native
import bpy
from .option_windows import F, Window
_OUTPUT = _dcc_source('Output geometry: NURBS only (Polygons / Bezier not made)')
_RANGE = _dcc_source('Curve range: Complete only (Partial not supported)')

def _degree(label):
    return {_dcc_source('Linear'): '1', _dcc_source('Cubic'): '3'}.get(label, label.split()[0])

def _run_loft(context, v):
    extra = {'output': 'POLYGONS'} if v.get('output') == _dcc_source('Polygons') else {}
    return bpy.ops.allset.loft('EXEC_DEFAULT', uniform=v['parameterization'] == _dcc_source('Uniform'), auto_reverse=v['auto_reverse'], close=v['close'], degree=_degree(v['degree']), section_spans=v['section_spans'], **extra)

def _run_revolve(context, v):
    return bpy.ops.allset.revolve('EXEC_DEFAULT', axis=v['axis'], pivot=v[_dcc_source('pivot')].upper(), pivot_point=tuple(v['pivot_point']), start_sweep=v['start_sweep'], end_sweep=v['end_sweep'], degree=_degree(v['degree']), segments=v['segments'])
_STYLES = {_dcc_source('Distance'): 'DISTANCE', _dcc_source('Flat'): 'FLAT', _dcc_source('Tube'): 'TUBE'}

def _run_extrude(context, v):
    direction = 'NORMAL' if v['direction'] == _dcc_source('Profile normal') else v['direction_vector'][0]
    return bpy.ops.allset.surface_extrude('EXEC_DEFAULT', style=_STYLES[v['style']], length=v['length'], direction=direction, result_position='PROFILE' if v['result_position'] == _dcc_source('At profile') else 'PATH', pivot='CLOSEST' if v[_dcc_source('pivot')] == _dcc_source('Closest end point') else 'COMPONENT')

def _run_birail1(context, v):
    return bpy.ops.allset.birail1('EXEC_DEFAULT', proportional=v['transform_control'] == _dcc_source('Proportional'))

def _boundary(kind):

    def run(context, v):
        return bpy.ops.allset.surface_boundary('EXEC_DEFAULT', kind=kind)
    return run

def _run_attach(context, v):
    return bpy.ops.allset.surface_attach('EXEC_DEFAULT', method=v['method'].upper(), bias=v['bias'], keep_originals=v['keep_originals'])

def _run_detach(context, v):
    return bpy.ops.allset.surface_detach('EXEC_DEFAULT', keep_original=v['keep_original'])
_REVERSE = {'U': 'U', 'V': 'V', _dcc_source('Swap'): 'SWAP', _dcc_source('Both'): 'BOTH'}

def _run_reverse(context, v):
    return bpy.ops.allset.surface_reverse('EXEC_DEFAULT', direction=_REVERSE[v['direction']])

def _run_rebuild(context, v):
    return bpy.ops.allset.surface_rebuild('EXEC_DEFAULT', spans_u=v['spans_u'], spans_v=v['spans_v'], degree_u=_degree(v['degree_u']), degree_v=_degree(v['degree_v']))

def _run_insert_isoparms(context, v):
    return bpy.ops.allset.surface_insert_isoparm('EXEC_DEFAULT', between=v['location'] == _dcc_source('Between selections'), increase=v['multiplicity'] == _dcc_source('Increase'), count=v['count'], keep_original=v['keep_original'])
REBUILD_DEGREES = (_dcc_source('1 Linear'), '2', _dcc_source('3 Cubic'), '5', '7')
